import 'package:flutter/material.dart'; import 'package:provider/provider.dart'; import '../core/app_state.dart'; import '../core/theme.dart';
class MyHelpScreen extends StatefulWidget{const MyHelpScreen({super.key});@override State<MyHelpScreen> createState()=>_MyHelpScreenState();}class _MyHelpScreenState extends State<MyHelpScreen>{List<dynamic> items=[];bool busy=true;@override void initState(){super.initState();load();}Future<void> load()async{items=await context.read<AppState>().api.mine();if(mounted)setState(()=>busy=false);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('My help activity')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Your requests',style:TextStyle(fontSize:26,fontWeight:FontWeight.w800)),const SizedBox(height:14),if(busy)const Center(child:CircularProgressIndicator(color:orange)),...items.map((x)=>Card(child:ListTile(title:Text(x['title']??''),subtitle:Text('${x['status']} • ${x['verificationStatus']}'),trailing:const Icon(Icons.chevron_right))))]));}
